export const DEFAULT_PALETTE_ID = 'codex';

export function getPaletteTheme(id: string): PaletteTheme {
	return PALETTE_THEMES.find(t => t.id === id) ?? PALETTE_THEMES.find(t => t.id === DEFAULT_PALETTE_ID)!;
}
